import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.Cs5aHXsR.js";var i=JSON.parse(`{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":1788010016000}`),a={name:`guide/getting-started.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to “Getting started”">​</a></h1><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to “Requirements”">​</a></h2><ul><li>Node.js 22 or newer, or Docker</li><li>A Google Cloud project — free, and you may already have one</li><li>A property in Search Console, or the ability to edit DNS for a domain you own</li></ul><h2 id="enable-the-apis" tabindex="-1">Enable the APIs <a class="header-anchor" href="#enable-the-apis" aria-label="Permalink to “Enable the APIs”">​</a></h2><p>This is the step everybody skips, and skipping it produces a 403 that reads as a permission problem. In the <a href="https://console.cloud.google.com/apis/library" target="_blank" rel="noreferrer">Google Cloud console</a>, enable the ones you need — they are three separate switches:</p><table tabindex="0"><thead><tr><th>API</th><th>Needed for</th></tr></thead><tbody><tr><td>Google Search Console API</td><td>Everything except ownership and indexing</td></tr><tr><td>Site Verification API</td><td><code>verify_site</code>, <code>get_verification_token</code>, <code>setup_site</code></td></tr><tr><td>Indexing API</td><td><code>request_indexing</code>, <code>get_indexing_status</code></td></tr></tbody></table><p>If you only want to read analytics, the first one is enough.</p><h2 id="get-a-credential" tabindex="-1">Get a credential <a class="header-anchor" href="#get-a-credential" aria-label="Permalink to “Get a credential”">​</a></h2><p>A <strong>service account</strong> is the recommended option. It sees only the properties you add it to, and deleting its key does not touch your own Google account.</p><ol><li>In the Cloud console, create a service account and download a JSON key.</li><li>Note its <code>client_email</code> — it looks like <code>something@project.iam.gserviceaccount.com</code>.</li><li>In Search Console, under Settings → Users and permissions, add that address. <strong>Owner</strong> if you want the Indexing API; <strong>Full</strong> is enough for everything else.</li></ol><p>For a property that does not exist yet, skip step 3 — <code>setup_site</code> will walk you through giving the service account ownership instead.</p><h2 id="configure-it" tabindex="-1">Configure it <a class="header-anchor" href="#configure-it" aria-label="Permalink to “Configure it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">export</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> GSC_SERVICE_ACCOUNT_KEY_FILE</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=~</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">/keys/gsc.json</span></span>
<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">export</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> GSC_SITE_URL</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">sc-domain:example.com     </span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;"># optional, defaults site_url</span></span></code></pre></div><p>The property spelling matters and is not guessed for you:</p><ul><li><code>sc-domain:example.com</code> — a <strong>domain property</strong>, covering every scheme, subdomain and port.</li><li><code>https://example.com/</code> — a <strong>URL-prefix property</strong>, covering exactly that prefix. The trailing slash is required.</li></ul><p>They are different properties holding different data, so <code>example.com</code> on its own is refused rather than resolved to one of them.</p><h2 id="run-it" tabindex="-1">Run it <a class="header-anchor" href="#run-it" aria-label="Permalink to “Run it”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @ni-c/google-search-console-mcp</span></span></code></pre></div><p>It starts even with no credential at all and lists its tools; every call then fails with setup instructions. That is deliberate, so registries and sandbox inspectors can introspect it.</p><h2 id="check-that-it-works" tabindex="-1">Check that it works <a class="header-anchor" href="#check-that-it-works" aria-label="Permalink to “Check that it works”">​</a></h2><p><code>list_sites</code> is the first call to make. It answers three questions at once: whether the credential works, which properties it can see, and what it may do with each.</p><p>An empty list is not an error — it is the normal state of a fresh service account nobody has granted anything to yet. A property listed as <code>siteUnverifiedUser</code> is listed but not verified, and every data call for it will return 403.</p><h2 id="set-up-a-property" tabindex="-1">Set up a property <a class="header-anchor" href="#set-up-a-property" aria-label="Permalink to “Set up a property”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>setup_site with site_url &quot;sc-domain:example.com&quot;</span></span></code></pre></div><p>It reports which of the four steps is missing and hands over the exact DNS record to create. Place it, then call <code>verify_site</code>, then <code>add_site</code>. The order matters: <code>add_site</code> on an unverified domain succeeds and leaves a property that answers 403 for everything.</p><h2 id="submit-a-sitemap" tabindex="-1">Submit a sitemap <a class="header-anchor" href="#submit-a-sitemap" aria-label="Permalink to “Submit a sitemap”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>submit_sitemap with feedpath &quot;https://example.com/sitemap.xml&quot;</span></span></code></pre></div><p>Success means Google accepted the address, not that the file is valid — it is fetched later. <code>get_sitemap</code> a few minutes afterwards shows <code>lastDownloaded</code>, the URL counts and any errors. To refresh a sitemap Google already knows, submit the same URL again; there is no separate update call.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};